# Output components
.components <- c(
  "meta_data",
  "response_data",
  "fixations",
  "raw_data"
)


#' Import eye-tracking data of a single participant
#'
#' Imports and pre-processes single participant eye-tracking data from EyeLink.
#'
#' @param eyelink_file Character(1). Path to the eye-tracking data (ASC file).
#' @param response_file Character(1). Path to the response data generated by
#'   ExperimentBuilder (TXT file).
#' @param response_cols Character. Column names of variables from the
#'   `response_file` that should be retained. If `NULL` (default), all columns
#'   of `response_file`. Note that all column names are put to lower case only
#'   before any renaming is applied.
#'
#' @returns A list with four components:
#' \describe{
#'   \item{\code{meta_data}}{Tibble. Single row containing EyeLink settings.}
#'   \item{\code{response_data}}{Tibble. Response data including all selected
#'   columns.}
#'   \item{\code{fixations}}{Tibble. Fixation times in a long format. Timestamps
#'   denoting stimulus presentation are in column `time_zero`, fixation start
#'   (`stime`) and end (`etime`) times are taken with respect to stimulus
#'   onset.}
#'   \item{\code{raw_data}}{Tibble. Raw Eyelink data as imported
#'   by [eyelinker::read_asc()].}
#' }
#'
#' @noRd
.import_eyelink_subject <- function(
    eyelink_file,
    response_file,
    response_cols = NULL
) {
  et_data <- eyelinker::read_asc(eyelink_file)
  resp_data <-
    readr::read_table(response_file, col_types = readr::cols()) |>
    dplyr::rename_with(tolower)

  if (is.null(response_cols)) {
    response_cols <- rlang::set_names(
      setdiff(colnames(resp_data), "trial_index")
    )
  } else {
    if (is.null(names(response_cols))) {
      names(response_cols) <- response_cols
    }
    response_cols <- tolower(response_cols)
  }

  k_et   <- max(et_data$raw$block)
  k_resp <- max(resp_data$trial_index)
  if (k_et != k_resp) {
    cli::cli_abort(c(
      "x" = "Eye-tracking and response data must have the same total number of trials.",
      "i" = "There {?is/are} {k_et} trial{?s} in eye-tracking data.",
      "i" = "There {?is/are} {k_resp} trial{?s} in response data."
    ))
  }

  timing_data <-
    et_data$msg |>
    dplyr::mutate(col = dplyr::case_when(
      stringr::str_detect(text, "graphics/VC")  ~ "zero",  # time of stimulus presentation
      stringr::str_detect(text, "blank_screen") ~ "blank", # time of showing post-trial blank screen
      .default = NA_character_
    )) |>
    tidyr::drop_na(col) |>
    dplyr::select(-"text") |>
    tidyr::pivot_wider(
      values_from  = "time",
      names_from   = "col",
      names_prefix = "time_"
    )

  fixation_data <-
    et_data$fix |>
    dplyr::left_join(
      timing_data,
      by = "block"
    ) |>
    dplyr::mutate(dplyr::across(
      .cols = tidyselect::ends_with("time"),
      .fns  = \(x) x - .data$time_zero
    ))

  response_data <-
    resp_data |>
    dplyr::left_join(
      timing_data,
      by = c("trial_index" = "block")
    ) |>
    dplyr::select("trial_index", dplyr::all_of(response_cols))

  rename_trials <- \(x) dplyr::rename(x, "trial_index" = "block")

  list(
    meta_data     = et_data$info,
    response_data = response_data,
    fixations     = rename_trials(fixation_data),
    raw_data      = rename_trials(et_data$raw)
  )
}


#' Import eye-tracking data from EyeLink
#'
#' Imports pre-processesed EyeLink eye-tracking data from a group of
#' participants.
#'
#' @param eyelink_dir Character(1). Contains path to a directory with
#'   eye-tracking data (ASC files).
#' @param response_dir Character(1). Contains path to a directory with response
#'   data generated by ExperimentBuilder (TXT files).
#' @param response_cols Character. Column names of variables from the
#'   `response_file` that should be retained. If `NULL` (default), all columns
#'   of `response_file`. Note that all column names are put to lower case only
#'   before any renaming is applied.
#'
#' @details
#' - Make sure that the ASC files in `eyelink_dir` and TXT files in
#'   `response_dir` follow the same naming convention.
#' - Common file name is used as the dataset's ID and added.
#' - At the moment, only ASC files are supported. Consequently, raw EDF data
#'   must be converted to ASC before using this function via the edf2asc
#'   utility.
#'
#' @return A list with four components:
#' \describe{
#'   \item{\code{meta_data}}{Tibble. Subject id and EyeLink settings. One row
#'   per a dataset}
#'   \item{\code{response_data}}{Tibble. Response data including subject
#'   id. One row per trial, multiple rows per a dataset.}
#'   \item{\code{fixations}}{Tibble. Fixation times in a long format.
#'   Timestamps denoting stimulus presentation are present in
#'   column `time_zero`, fixation start (`stime`) and end (`etime`)
#'   times are taken with respect to stimulus onset. Contains
#'   multiple rows per a dataset.}
#'   \item{\code{raw_data}}{List. A list of tibbles containing raw
#'   Eyelink data as imported by [eyelinker::read_asc()] without
#'   dataset ID added.}
#' }
#'
#' @export
import_eyelink_data <- function(
    eyelink_dir,
    response_dir,
    response_cols = NULL
) {
  # --- Discover files ---------------------------------------------------------
  eyelink_files  <- list.files(eyelink_dir,  full.names = TRUE, pattern = "\\.asc$")
  response_files <- list.files(response_dir, full.names = TRUE, pattern = "\\.txt$")

  eyelink_ids  <- tools::file_path_sans_ext(basename(eyelink_files))
  response_ids <- tools::file_path_sans_ext(basename(response_files))

  # --- ID matching ------------------------------------------------------------
  both_present      <- intersect(eyelink_ids, response_ids)
  eye_only_present  <- setdiff(eyelink_ids, response_ids)
  resp_only_present <- setdiff(response_ids, eyelink_ids)

  if (rlang::is_empty(both_present)) {
    cli::cli_abort(c(
      "!" = "EyeLink and response data must use the same naming convention.",
      "x" = "There are no EyeLink and response data with an identical id.",
      "i" = "EyeLink data come from {.path {eyelink_dir}}.",
      "i" = "Response data come from {.path {response_dir}}."
    ))
  }

  if (!rlang::is_empty(resp_only_present)) {
    cli::cli_inform(c(
      "!" = "The following dataset{?s} will not be imported because of missing EyeLink data: {.val {resp_only_present}}"
    ))
  }

  if (!rlang::is_empty(eye_only_present)) {
    cli::cli_inform(c(
      "!" = "The following dataset{?s} will not be imported because of missing response data: {.val {eye_only_present}}"
    ))
  }

  all_files <-
    dplyr::inner_join(
      tibble::tibble(id = eyelink_ids,  eye_path = eyelink_files),
      tibble::tibble(id = response_ids, resp_path = response_files),
      by = "id"
    )

  n_datasets <- nrow(all_files)
  cli::cli_inform(c(
    "i" = "Importing data from {n_datasets} unique dataset{?s}."
  ))

  # --- Import loop ------------------------------------------------------------
  safe_import <- purrr::safely(.import_eyelink_subject)
  raw_data <-
    purrr::pmap(
      list(
        eye_path  = all_files$eye_path,
        resp_path = all_files$resp_path
      ),
      \(eye_path, resp_path) safe_import(
        eyelink_file  = eye_path,
        response_file = resp_path,
        response_cols = response_cols
      ),
      .progress = TRUE
    ) |>
    rlang::set_names(all_files$id)

  # --- Report errors ----------------------------------------------------------
  errors    <- purrr::keep(purrr::map(raw_data, "error"), Negate(is.null))
  successes <- purrr::keep(purrr::map(raw_data, "result"), Negate(is.null))

  if (!rlang::is_empty(errors)) {
    error_lines <- paste0(
      names(errors), ": ",
      purrr::map_chr(errors, conditionMessage)
    )
    cli::cli_warn(c(
      "!" = "{length(errors)}/{n_datasets} dataset{?s} failed to import and {?was/were} excluded.",
      rlang::set_names(error_lines, rep("x", length(error_lines)))
    ))
  }

  if (rlang::is_empty(successes)) {
    cli::cli_abort("No datasets were successfully imported.")
  }

  cli::cli_inform(c(
    "v" = "Successfully imported {length(successes)}/{n_datasets} unique dataset{?s}."
  ))

  # --- Assemble output --------------------------------------------------------
  purrr::map(
    rlang::set_names(.components),
    \(comp) {
      if (comp == "raw_data") {
        purrr::map(successes, \(d) d[[comp]])
      } else {
        purrr::map(successes, \(d) d[[comp]]) |>
          purrr::list_rbind(names_to = "dataset_id")
      }
    }
  )
}
